import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"CLI Reference","description":"Every Protection Plus command — run, scan, status, config, test-alert, rules update, debug-conns and version — with syntax, example output, and when to use each.","frontmatter":{"title":"CLI Reference","description":"Every Protection Plus command — run, scan, status, config, test-alert, rules update, debug-conns and version — with syntax, example output, and when to use each."},"headers":[],"relativePath":"protection/user-guide/cli.md","filePath":"protection/user-guide/cli.md","lastUpdated":1785339549000}'),i={name:"protection/user-guide/cli.md"};function o(l,e,c,p,r,d){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p>Protection Plus is the system command <code>protection</code>. It needs <strong>root</strong> for full process/network introspection and enforcement. Everything below was verified against Protection Plus <strong>v1.0.0</strong>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>protection plus — container-host abuse protection</span></span>
<span class="line"><span></span></span>
<span class="line"><span>USAGE:</span></span>
<span class="line"><span>  protection &lt;command&gt; [flags]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>COMMANDS:</span></span>
<span class="line"><span>  run                  Start the protection daemon</span></span>
<span class="line"><span>  scan                 Run all detectors once and print findings (no enforcement)</span></span>
<span class="line"><span>  status               Show configuration and Docker connectivity</span></span>
<span class="line"><span>  config init [path]   Write a starter configuration file</span></span>
<span class="line"><span>  config check [path]  Validate a configuration file</span></span>
<span class="line"><span>  test-alert           Send a synthetic alert through every configured channel</span></span>
<span class="line"><span>  rules update         Download the latest YARA rules and hash blocklist</span></span>
<span class="line"><span>  debug-conns [port]   List all connections seen (host + every container)</span></span>
<span class="line"><span>  version              Print version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FLAGS:</span></span>
<span class="line"><span>  --config &lt;path&gt;      Path to config (default: /etc/protection/config.yaml)</span></span></code></pre></div><hr><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--config &lt;path&gt;</code></td><td>Path to the config file. Defaults to <code>/etc/protection/config.yaml</code>. Works with <code>run</code>, <code>scan</code>, <code>status</code>, <code>test-alert</code> and <code>rules update</code>.</td></tr></tbody></table><p><code>protection config</code> takes its target path as a positional argument instead (<code>protection config check ./config.yaml</code>), falling back to the same default when omitted.</p><hr><h2 id="protection-run" tabindex="-1"><code>protection run</code> <a class="header-anchor" href="#protection-run" aria-label="Permalink to &quot;\`protection run\`&quot;">​</a></h2><p>Start the daemon. This is what the systemd unit executes. Aliases: <code>start</code>, <code>daemon</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/protection/config.yaml</span></span></code></pre></div><p>On startup it also refreshes threat intel (YARA rules + hash blocklist) when <code>intel.enabled</code> is set, then keeps updating it on the configured interval. If run as a non-root user it warns that introspection and enforcement may be limited, but still starts.</p><p><strong>When to use:</strong> under systemd in production. For a foreground test run, just <code>Ctrl-C</code> to stop (it shuts down gracefully on <code>SIGINT</code>/<code>SIGTERM</code>).</p><p>Example log output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2026-07-29 14:02:11 [INFO ] threat-intel updated: 45231 bytes of YARA rules, 184112 blocklist hashes</span></span>
<span class="line"><span>2026-07-29 14:02:11 [INFO ] protection engine started: 10 detectors, 1 alert channels, interval=5s, dry_run=false</span></span>
<span class="line"><span>2026-07-29 14:02:16 [WARN ] [HIGH] Known miner binary detected — Process &quot;xmrig&quot; matches a known miner signature.</span></span>
<span class="line"><span>2026-07-29 14:02:16 [INFO ] running action &quot;neutralize&quot; on process xmrig (pid 595693)</span></span>
<span class="line"><span>2026-07-29 14:02:16 [INFO ] neutralized process pid 595693 (xmrig)</span></span></code></pre></div><hr><h2 id="protection-scan" tabindex="-1"><code>protection scan</code> <a class="header-anchor" href="#protection-scan" aria-label="Permalink to &quot;\`protection scan\`&quot;">​</a></h2><p>Run every detector <strong>once</strong>, print a findings table, and take <strong>no</strong> action. Shows a live spinner while scanning.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scan</span></span></code></pre></div><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SEVERITY  CATEGORY  TARGET                      TITLE</span></span>
<span class="line"><span>high      miner     process xmrig (pid 621221)  Known miner binary detected</span></span>
<span class="line"><span>high      zipbomb   /var/lib/.../bomb.zip       Decompression bomb detected</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2 finding(s)</span></span></code></pre></div><p>When nothing is found it prints <code>✓ no threats detected</code>.</p><p><strong>When to use:</strong> to verify detection works, to audit a node on demand, or in a cron/monitoring check. It never enforces, so it&#39;s always safe to run.</p><div class="tip custom-block"><p class="custom-block-title">Run a scan before arming enforcement</p><p>While <code>dry_run: true</code>, the daemon only logs what it <em>would</em> do. Run <code>protection scan</code> a few times on a busy node first — if it flags your legitimate workloads, tune the detectors (or whitelist paths) <strong>before</strong> you set <code>dry_run: false</code>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The spinner is automatically suppressed when output is piped (e.g. <code>protection scan | tee report.txt</code>), keeping logs clean.</p></div><hr><h2 id="protection-status" tabindex="-1"><code>protection status</code> <a class="header-anchor" href="#protection-status" aria-label="Permalink to &quot;\`protection status\`&quot;">​</a></h2><p>Show the loaded config, protection mode, enabled detectors/alerts, and Docker connectivity.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config:        /etc/protection/config.yaml (ok)</span></span>
<span class="line"><span>installation:  node-fra-01</span></span>
<span class="line"><span>mode:          both</span></span>
<span class="line"><span>scan interval: 5s</span></span>
<span class="line"><span>dry run:       true</span></span>
<span class="line"><span>detectors:     miner, portscan, ddos, zipbomb, exploit, abuse, yara, fim, trivy, onaccess</span></span>
<span class="line"><span>alerts:        discord</span></span>
<span class="line"><span>docker:        connected via /var/run/docker.sock</span></span></code></pre></div><p>If Docker is disabled in config the last line reads <code>docker: disabled</code>; if it is enabled but the socket ping fails you get <code>docker: UNREACHABLE (...)</code>.</p><p><strong>When to use:</strong> first thing after install or after editing config — confirms what&#39;s enabled and that Docker is reachable.</p><hr><h2 id="protection-config-init" tabindex="-1"><code>protection config init</code> <a class="header-anchor" href="#protection-config-init" aria-label="Permalink to &quot;\`protection config init\`&quot;">​</a></h2><p>Write a fully-commented starter config (in dry-run mode), then validate what it wrote so a bad flag fails loudly.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/protection/config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># wrote starter config to /etc/protection/config.yaml</span></span></code></pre></div><p>It refuses to overwrite an existing file and creates missing parent directories automatically. The installer calls this with flags to pre-fill values:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Sets</th></tr></thead><tbody><tr><td><code>--name &lt;name&gt;</code></td><td><code>general.name</code> (defaults to a generated display name)</td></tr><tr><td><code>--mode &lt;server|docker|both&gt;</code></td><td><code>general.mode</code> (invalid values fall back to <code>both</code>)</td></tr><tr><td><code>--dry-run &lt;true|false&gt;</code></td><td><code>general.dry_run</code> (defaults to <code>true</code>)</td></tr><tr><td><code>--discord-webhook &lt;url&gt;</code></td><td>enables Discord alerts with this webhook</td></tr><tr><td><code>--pterodactyl-url &lt;url&gt;</code></td><td>Pterodactyl panel URL</td></tr><tr><td><code>--pterodactyl-key &lt;key&gt;</code></td><td>Pterodactyl Application API key (Pterodactyl integration is only enabled when <strong>both</strong> URL and key are given)</td></tr><tr><td><code>--scan-paths &lt;list&gt;</code></td><td>comma-separated archive-scan paths — see below</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/protection/config.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node-fra-01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> both</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --discord-webhook</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://discord.com/api/webhooks/…&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --pterodactyl-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://panel.example.com&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --pterodactyl-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ptla_…&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --scan-paths</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/var/lib/pterodactyl/volumes,/home&quot;</span></span></code></pre></div><h3 id="the-scan-paths-all-expansion" tabindex="-1">The <code>--scan-paths ALL</code> expansion <a class="header-anchor" href="#the-scan-paths-all-expansion" aria-label="Permalink to &quot;The \`--scan-paths ALL\` expansion&quot;">​</a></h3><p>Passing the literal value <code>ALL</code> (case-insensitive) makes <code>config init</code> expand to the full set of user-writable directories Protection Plus should scan:</p><ul><li>always: <code>/tmp</code>, <code>/var/tmp</code>, <code>/dev/shm</code>, <code>/home</code></li><li>added only if they exist on the host: <code>/var/lib/pterodactyl/volumes</code>, <code>/var/lib/pterodactyl/mounts</code>, <code>/var/www</code>, <code>/srv</code>, <code>/opt</code></li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --scan-paths</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span></span></code></pre></div><p>Omitting <code>--scan-paths</code> writes just the default <code>/var/lib/pterodactyl/volumes</code>.</p><hr><h2 id="protection-config-check" tabindex="-1"><code>protection config check</code> <a class="header-anchor" href="#protection-config-check" aria-label="Permalink to &quot;\`protection config check\`&quot;">​</a></h2><p>Validate a config file without running the daemon.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/protection/config.yaml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✓ /etc/protection/config.yaml is valid</span></span></code></pre></div><p><strong>When to use:</strong> after every manual edit, before <code>systemctl restart protection</code>. It catches mode typos, enabled-but-unconfigured alert channels, and YAML errors.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Make <code>protection config check</code> part of your edit loop. A config that parses but fails validation is caught here — before systemd restart-loops the daemon on it.</p></div><hr><h2 id="protection-test-alert" tabindex="-1"><code>protection test-alert</code> <a class="header-anchor" href="#protection-test-alert" aria-label="Permalink to &quot;\`protection test-alert\`&quot;">​</a></h2><p>Send a synthetic <strong>critical</strong> alert through every enabled channel. Fails with an error if no channels are enabled.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-alert</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ discord: delivered</span></span>
<span class="line"><span>✗ smtp: dial tcp: connection refused</span></span></code></pre></div><p><strong>When to use:</strong> right after configuring alerts, to confirm Discord/email/webhook all work end-to-end.</p><hr><h2 id="protection-rules-update" tabindex="-1"><code>protection rules update</code> <a class="header-anchor" href="#protection-rules-update" aria-label="Permalink to &quot;\`protection rules update\`&quot;">​</a></h2><p>Download the latest threat intel: the curated <strong>YARA rule bundle</strong> and the <strong>MalwareBazaar SHA-256 hash blocklist</strong>. Each source is attempted independently — one failing doesn&#39;t block the other (you&#39;ll get a partial-update error, and whatever succeeded is kept).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rules</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Downloading threat intel (YARA rules + hash blocklist)…</span></span>
<span class="line"><span>✓ rules: 45231 bytes -&gt; /etc/protection/yara/protection.yar</span></span>
<span class="line"><span>✓ blocklist: 184112 hashes -&gt; /var/lib/protection/blocklist.sha256</span></span></code></pre></div><p><strong>When to use:</strong> on first install (the YARA and on-access scanners need these files), after changing <code>intel.rules_url</code>/<code>intel.hashlist_url</code>, or to force a refresh instead of waiting for the daemon&#39;s automatic 24h update cycle. Downloads are atomic (temp file + rename), so a running daemon never sees a partial file.</p><hr><h2 id="protection-debug-conns" tabindex="-1"><code>protection debug-conns</code> <a class="header-anchor" href="#protection-debug-conns" aria-label="Permalink to &quot;\`protection debug-conns\`&quot;">​</a></h2><p>List <strong>every</strong> TCP connection Protection Plus can see — across the host and every container network namespace — with the owning PID and container. Optionally filter by remote (or local) port.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug-conns</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # all connections</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug-conns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3333</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # only connections involving port 3333</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>STATE   LOCAL              REMOTE        PID     PROCESS  CONTAINER</span></span>
<span class="line"><span>ESTAB   172.17.0.2:40959   1.1.1.1:80    637740  nc       07ed098c54bc</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 connection(s)</span></span></code></pre></div><p>States shown include <code>ESTAB</code>, <code>SYN_SENT</code> and raw socket states; container IDs are truncated to 12 characters.</p><p><strong>When to use:</strong> to confirm a suspected pool/scan connection, or to debug attribution.</p><div class="tip custom-block"><p class="custom-block-title">Verifying container visibility</p><p>This is the quickest way to prove Protection Plus sees a container&#39;s traffic that never appears in the host&#39;s <code>/proc/net/tcp</code>. If <code>debug-conns</code> shows container IDs in the last column, namespace introspection is working — if it&#39;s always empty, check that the daemon runs as root and can reach the Docker socket.</p></div><hr><h2 id="protection-version" tabindex="-1"><code>protection version</code> <a class="header-anchor" href="#protection-version" aria-label="Permalink to &quot;\`protection version\`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">protection</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># protection 1.0.0</span></span></code></pre></div><p>Also available as <code>-v</code> / <code>--version</code>.</p><hr><h2 id="protection-help" tabindex="-1"><code>protection help</code> <a class="header-anchor" href="#protection-help" aria-label="Permalink to &quot;\`protection help\`&quot;">​</a></h2><p>Print the usage summary shown at the top of this page. Also available as <code>-h</code> / <code>--help</code>, and shown automatically (with exit code <code>2</code>) when you run an unknown command.</p><hr><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>0</code></td><td>Success</td></tr><tr><td><code>1</code></td><td>Runtime error (printed to stderr)</td></tr><tr><td><code>2</code></td><td>Usage error (unknown command / missing argument)</td></tr></tbody></table><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><strong><a href="./detection">How Detection Works →</a></strong> — what each detector checks.</li><li><strong><a href="./alerts">Alerts →</a></strong> — channel setup and payloads.</li><li><strong><a href="./actions-rules">Actions &amp; Rules →</a></strong> — enforcement policy.</li></ul>`,83)])])}const u=s(i,[["render",o]]);export{g as __pageData,u as default};
